import 'dart:convert';
import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';

class AppDatabase {
 AppDatabase._(); static final instance=AppDatabase._(); Database? _db;
 Future<Database> get database async{if(_db!=null)return _db!;final root=await getDatabasesPath();_db=await openDatabase(join(root,'qamvio_pos.db'),version:2,onConfigure:(d)=>d.execute('PRAGMA foreign_keys = ON'),onCreate:_create,onUpgrade:(d,o,n)async{if(o<2)await _v2(d);});return _db!;}
 Future<void> _create(Database d,int v)async{
  await d.execute('CREATE TABLE products(id TEXT PRIMARY KEY,name TEXT NOT NULL,sku TEXT,barcode TEXT,cost REAL NOT NULL DEFAULT 0,price REAL NOT NULL DEFAULT 0,stock REAL NOT NULL DEFAULT 0,category TEXT,updated_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT,address TEXT,balance REAL NOT NULL DEFAULT 0,updated_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE suppliers(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT,address TEXT,balance REAL NOT NULL DEFAULT 0,updated_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE sales(id TEXT PRIMARY KEY,invoice_no TEXT NOT NULL,customer_id TEXT,salesman_id TEXT,subtotal REAL NOT NULL DEFAULT 0,discount REAL NOT NULL DEFAULT 0,paid REAL NOT NULL DEFAULT 0,total REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE sale_items(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL,product_id TEXT,product_name TEXT NOT NULL,qty REAL NOT NULL,price REAL NOT NULL,total REAL NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE)');
  await d.execute('CREATE TABLE purchases(id TEXT PRIMARY KEY,supplier_id TEXT,total REAL NOT NULL DEFAULT 0,paid REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE expenses(id TEXT PRIMARY KEY,name TEXT NOT NULL,amount REAL NOT NULL DEFAULT 0,note TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE salesmen(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT,active INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE sync_queue(id INTEGER PRIMARY KEY AUTOINCREMENT,entity TEXT NOT NULL,entity_id TEXT NOT NULL,operation TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,synced INTEGER NOT NULL DEFAULT 0)');
  await d.execute('CREATE TABLE fuel_tanks(id TEXT PRIMARY KEY,name TEXT NOT NULL,fuel_type TEXT NOT NULL,capacity REAL NOT NULL DEFAULT 0,current_stock REAL NOT NULL DEFAULT 0,updated_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE fuel_nozzles(id TEXT PRIMARY KEY,tank_id TEXT NOT NULL,name TEXT NOT NULL,meter_reading REAL NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,FOREIGN KEY(tank_id) REFERENCES fuel_tanks(id))');
  await _v2(d);
 }
 Future<void> _v2(Database d)async{
  await d.execute("CREATE TABLE IF NOT EXISTS business_profile(id TEXT PRIMARY KEY,business_name TEXT NOT NULL,business_type TEXT NOT NULL,phone TEXT,address TEXT,currency TEXT NOT NULL DEFAULT 'AFN',updated_at TEXT NOT NULL)");
  await d.execute('CREATE TABLE IF NOT EXISTS purchase_items(id TEXT PRIMARY KEY,purchase_id TEXT NOT NULL,product_id TEXT,product_name TEXT NOT NULL,qty REAL NOT NULL,cost REAL NOT NULL,total REAL NOT NULL,FOREIGN KEY(purchase_id) REFERENCES purchases(id) ON DELETE CASCADE)');
  await d.execute('CREATE TABLE IF NOT EXISTS customer_payments(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL,amount REAL NOT NULL,note TEXT,created_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE IF NOT EXISTS supplier_payments(id TEXT PRIMARY KEY,supplier_id TEXT NOT NULL,amount REAL NOT NULL,note TEXT,created_at TEXT NOT NULL)');
  await d.execute('CREATE TABLE IF NOT EXISTS fuel_shifts(id TEXT PRIMARY KEY,nozzle_id TEXT NOT NULL,salesman_id TEXT,opening_meter REAL NOT NULL DEFAULT 0,closing_meter REAL NOT NULL DEFAULT 0,unit_price REAL NOT NULL DEFAULT 0,cash_received REAL NOT NULL DEFAULT 0,expense REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)');
 }
 String _id()=>DateTime.now().microsecondsSinceEpoch.toString(); String _now()=>DateTime.now().toUtc().toIso8601String();
 Future<void> _queue(DatabaseExecutor t,String e,String id,Map<String,Object?> p)async=>t.insert('sync_queue',{'entity':e,'entity_id':id,'operation':'upsert','payload':jsonEncode(p),'created_at':_now(),'synced':0});
 Future<List<Map<String,Object?>>> list(String table,{String? orderBy})async=>(await database).query(table,orderBy:orderBy);
 Future<List<Map<String,Object?>>> listProducts()=>list('products',orderBy:'name COLLATE NOCASE'); Future<List<Map<String,Object?>>> listCustomers()=>list('customers',orderBy:'name COLLATE NOCASE'); Future<List<Map<String,Object?>>> listSuppliers()=>list('suppliers',orderBy:'name COLLATE NOCASE'); Future<List<Map<String,Object?>>> listExpenses()=>list('expenses',orderBy:'created_at DESC'); Future<List<Map<String,Object?>>> listSales()=>list('sales',orderBy:'created_at DESC'); Future<List<Map<String,Object?>>> listFuelTanks()=>list('fuel_tanks',orderBy:'name COLLATE NOCASE');
 Future<void> saveProduct({required String name,String sku='',double cost=0,double price=0,double stock=0})async{final d=await database,id=_id(),now=_now();final r=<String,Object?>{'id':id,'name':name,'sku':sku,'barcode':sku,'cost':cost,'price':price,'stock':stock,'category':'','updated_at':now};await d.transaction((t)async{await t.insert('products',r);await _queue(t,'products',id,r);});}
 Future<void> saveCustomer({required String name,String phone='',String address=''})async{final d=await database,id=_id(),now=_now();final r=<String,Object?>{'id':id,'name':name,'phone':phone,'address':address,'balance':0.0,'updated_at':now};await d.transaction((t)async{await t.insert('customers',r);await _queue(t,'customers',id,r);});}
 Future<void> saveSupplier({required String name,String phone='',String address=''})async{final d=await database,id=_id(),now=_now();final r=<String,Object?>{'id':id,'name':name,'phone':phone,'address':address,'balance':0.0,'updated_at':now};await d.transaction((t)async{await t.insert('suppliers',r);await _queue(t,'suppliers',id,r);});}
 Future<void> saveExpense({required String name,required double amount,String note=''})async{final d=await database,id=_id(),now=_now();final r=<String,Object?>{'id':id,'name':name,'amount':amount,'note':note,'created_at':now,'updated_at':now};await d.transaction((t)async{await t.insert('expenses',r);await _queue(t,'expenses',id,r);});}
 Future<void> saveFuelTank({required String name,required String fuelType,double capacity=0})async{final d=await database,id=_id(),now=_now();final r=<String,Object?>{'id':id,'name':name,'fuel_type':fuelType,'capacity':capacity,'current_stock':0.0,'updated_at':now};await d.transaction((t)async{await t.insert('fuel_tanks',r);await _queue(t,'fuel_tanks',id,r);});}
 Future<String> createSale({required List<Map<String,Object?>> items,double discount=0,double paid=0})async{if(items.isEmpty)throw ArgumentError('items');final d=await database,id=_id(),now=_now(),inv='INV-${DateTime.now().millisecondsSinceEpoch}';final subtotal=items.fold<double>(0,(a,x)=>a+(x['qty'] as num).toDouble()*(x['price'] as num).toDouble());final total=(subtotal-discount).clamp(0,double.infinity).toDouble();await d.transaction((t)async{final s=<String,Object?>{'id':id,'invoice_no':inv,'customer_id':null,'salesman_id':null,'subtotal':subtotal,'discount':discount,'paid':paid,'total':total,'created_at':now,'updated_at':now};await t.insert('sales',s);var n=0;for(final x in items){final q=(x['qty'] as num).toDouble(),p=(x['price'] as num).toDouble();await t.insert('sale_items',{'id':'${id}_${n++}','sale_id':id,'product_id':x['product_id'],'product_name':x['product_name'],'qty':q,'price':p,'total':q*p});await t.rawUpdate('UPDATE products SET stock=stock-?,updated_at=? WHERE id=?',[q,now,x['product_id']]);}await _queue(t,'sales',id,s);});return inv;}
 Future<Map<String,num>> dashboardTotals()async{final d=await database;num one(String k,List<Map<String,Object?>> r)=>r.first[k] as num;return {'sales':Sqflite.firstIntValue(await d.rawQuery('SELECT COUNT(*) FROM sales'))??0,'products':Sqflite.firstIntValue(await d.rawQuery('SELECT COUNT(*) FROM products'))??0,'customers':Sqflite.firstIntValue(await d.rawQuery('SELECT COUNT(*) FROM customers'))??0,'revenue':one('v',await d.rawQuery('SELECT COALESCE(SUM(total),0) v FROM sales')),'expenses':one('v',await d.rawQuery('SELECT COALESCE(SUM(amount),0) v FROM expenses'))};}
}
